def handle_a(item):
    value = item["value"] * 2
    return {"id": item["id"], "value": value, "category": "high" if value > 100 else "low"}


def handle_b(item):
    value = item["value"] + 50
    return {"id": item["id"], "value": value, "category": "adjusted"}


def handle_c(item):
    value = item["value"]
    if value < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": value, "category": "passthrough"}


HANDLERS = {
    "A": handle_a,
    "B": handle_b,
    "C": handle_c,
}


def dispatch(item):
    handler = HANDLERS.get(item.get("type"))
    return handler(item) if handler else None


def process_data(data):
    return [result for item in data if (result := dispatch(item)) is not None]
