interface Preferences {
  theme: string;
  notifications: boolean;
  language: string;
}

interface User {
  id: number;
  name: string;
  email: string;
  preferences: Preferences;
  tags: string[];
  last_login: string; // ISO 8601 timestamp
  metadata?: string | null; // observed as None → null; see note
}

function validateUser(user: unknown): asserts user is User {
  if (typeof user !== "object" || user === null) {
    throw new Error("User must be an object");
  }
  const u = user as Record<string, unknown>;

  if (typeof u.id !== "number" || !Number.isInteger(u.id)) {
    throw new Error("id must be an integer");
  }
  if (typeof u.name !== "string" || u.name.length === 0) {
    throw new Error("name must be a non-empty string");
  }
  if (typeof u.email !== "string" || !u.email.includes("@")) {
    throw new Error("email must be a string containing '@'");
  }
  if (
    typeof u.preferences !== "object" ||
    u.preferences === null ||
    typeof (u.preferences as any).theme !== "string" ||
    typeof (u.preferences as any).notifications !== "boolean" ||
    typeof (u.preferences as any).language !== "string"
  ) {
    throw new Error("preferences must have string theme, boolean notifications, string language");
  }
  if (!Array.isArray(u.tags) || !u.tags.every((t) => typeof t === "string")) {
    throw new Error("tags must be an array of strings");
  }
  if (u.metadata !== undefined && u.metadata !== null && typeof u.metadata !== "string") {
    throw new Error("metadata must be null, undefined, or a string");
  }
}
```

Notes on inference choices:
- **metadata**: observed value is `None` (`null`), so it's nullable. I made it optional-and-nullable (`string | null`) rather than strictly `null`, since "metadata" commonly carries other shapes — but that's an inference, not something the usage proves. If it can only ever be `null`, use `metadata: null`.
- **last_login**: typed as `string` (ISO 8601). Add a branded type if you need compile-time timestamp validation.
- Field names kept in `snake_case` (`last_login`) to match the source usage; convert to `camelCase` if you prefer TS convention.
- `validateUser` uses an `asserts` signature so callers get a narrowed `User` after it passes, mirroring the Python `assert` style.
